1314 |     /// Minimize retained payload bytes first, then expected traversal work.
1315 |     /// If both are equal, keep the physical runs and avoid another allocation.
1316 |     fn select_plan(runs: &RleRuns) -> LevelPlan {
1317 |         if runs.num_values() == 0 {
1318 |             return LevelPlan::Dense;
1319 |         }
1320 | 
1321 |         let run_storage_size = std::mem::size_of::<RunStorage>() as u128;
1322 |         let physical_size = run_storage_size + runs.owned_size() as u128;
1323 |         let coalesced_size = run_storage_size
1324 |             + (runs.coalesced_runs() as u128)
1325 |                 * (std::mem::size_of::<u16>() + RunEnds::width_for(runs.num_values())) as u128;
1326 |         let dense_size = (runs.num_values() as u128) * std::mem::size_of::<u16>() as u128;
1327 |         [
1328 |             (physical_size, runs.num_runs(), 0usize, LevelPlan::Physical),
1329 |             (
1330 |                 coalesced_size,
1331 |                 runs.coalesced_runs(),
1332 |                 1usize,
1333 |                 LevelPlan::Coalesced,
1334 |             ),
1335 |             (dense_size, runs.num_values(), 2usize, LevelPlan::Dense),
1336 |         ]
1337 |         .into_iter()
1338 |         .min_by_key(|(size, traversal, priority, _)| (*size, *traversal, *priority))
1339 |         .map(|(_, _, _, plan)| plan)
1340 |         .unwrap_or(LevelPlan::Dense)
1341 |     }
