1343 |     fn build_coalesced(runs: RleRuns) -> Result<Self> {
1344 |         let mut values = Vec::with_capacity(runs.coalesced_runs());
1345 |         let mut ends = RunEndsBuilder::with_capacity(runs.num_values(), runs.coalesced_runs());
1346 |         let mut logical_end = 0usize;
1347 |         for (value, length) in runs.iter() {
1348 |             logical_end = logical_end
1349 |                 .checked_add(length)
1350 |                 .ok_or_else(|| Error::internal("Validated RLE run length sum overflowed usize"))?;
1351 |             if values.last().copied() == Some(value) {
1352 |                 ends.set_last(logical_end)?;
1353 |             } else {
1354 |                 values.push(value);
1355 |                 ends.push(logical_end)?;
1356 |             }
1357 |         }
1358 |         Ok(Self::Runs(Arc::new(RunStorage::Coalesced {
1359 |             values: values.into_boxed_slice(),
1360 |             ends: ends.finish(),
1361 |         })))
1362 |     }
